pts = [-100, -80, -60, -40, -20, 0, 20, 40, 60, 80, 100]
vals = [2, 6, 10, 22, 34, 33, 28, 22, 15, 7, 3]

def interp(x):
    if x <= pts[0] or x >= pts[-1]:
        return 0
    for i in range(len(pts)-1):
        if pts[i] <= x <= pts[i+1]:
            t = (x - pts[i]) / (pts[i+1] - pts[i])
            return vals[i] + t * (vals[i+1] - vals[i])
    return 0

pitch = 50
for y_test in range(0, 50, 5):
    total = sum(interp(y_test - k * pitch) for k in range(-10, 11))
    print(f"y={y_test}: {total:.1f} um")
'

